class Solution {

    /**
     * @param Integer[] $salary
     * @return Float
     */
    function average($salary) {
        $sum = array_sum($salary);
        $mn = min($salary);
        $mx = max($salary);
        $n = count($salary);
        return (float)($sum - $mn - $mx) / ($n - 2);
    }
}
