    function numFactoredBinaryTrees($arr) {
        $MOD = 1000000007;
        sort($arr);
        $n = count($arr);
        $dp = [];
        $total = 0;
        for ($i = 0; $i < $n; $i++) {
            $x = $arr[$i];
            $cnt = 1;
            for ($j = 0; $j < $i; $j++) {
                $a = $arr[$j];
                if ($a * 2 > $x) break;
                if ($x % $a != 0) continue;
                $b = intdiv($x, $a);
                if (isset($dp[$b])) {
                    $cnt = ($cnt + ($dp[$a] * $dp[$b]) % $MOD) % $MOD;
