            $fm1 = $freq[$maxf - 1] ?? 0;
            if ($maxf == 1
                || $fm * $maxf + 1 == $len
                || $fm1 * ($maxf - 1) + $maxf == $len) {
                $ans = $len;
            }
        }
        return $ans;
    }
}
```

