class Solution {

    /**
     * @param Integer[] $flowers
     * @param Integer $newFlowers
     * @param Integer $target
     * @param Integer $full
     * @param Integer $partial
     * @return Integer
     */
    function maximumBeauty($flowers, $newFlowers, $target, $full, $partial) {
        $n = count($flowers);
        foreach ($flowers as $i => $f) {
            if ($f > $target) $flowers[$i] = $target;
        }
        sort($flowers);
        $prefix = array_fill(0, $n + 1, 0);
        for ($i = 0; $i < $n; $i++) {
            $prefix[$i + 1] = $prefix[$i] + $flowers[$i];
        }
        $best = 0;
        $j = $n;
        $cost = 0;
        for ($k = 0; $k <= $n; $k++) {
            if ($k > 0) {
                $cost += $target - $flowers[$n - $k];
            }
            if ($cost > $newFlowers) break;
            $rem = $newFlowers - $cost;
            if ($k == $n) {
                $best = max($best, $n * $full);
                break;
            }
            if ($j > $n - $k) $j = $n - $k;
            while ($j > 0 && $flowers[$j - 1] * $j - $prefix[$j] > $rem) $j--;
            $mn = intdiv($prefix[$j] + $rem, $j);
            if ($mn > $target - 1) $mn = $target - 1;
            $val = $k * $full + $mn * $partial;
            if ($val > $best) $best = $val;
        }
        return $best;
    }
}
