```php
class Solution {

    /**
     * @param Integer $maxTime
     * @param Integer[][] $edges
     * @param Integer[] $passingFees
     * @return Integer
     */
    function minCost($maxTime, $edges, $passingFees) {
        $n = count($passingFees);
        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $adj[$e[0]][] = [$e[1], $e[2]];
            $adj[$e[1]][] = [$e[0], $e[2]];
        }
        $INF = PHP_INT_MAX;
        $minTime = array_fill(0, $n, $INF);
        $pq = new SplPriorityQueue();
        $pq->setExtractFlags(SplPriorityQueue::EXTR_DATA);
        $pq->insert([$passingFees[0], 0, 0], -$passingFees[0]);
        while (!$pq->isEmpty()) {
            [$cost, $time, $u] = $pq->extract();
            if ($u == $n - 1) return $cost;
            if ($time >= $minTime[$u]) continue;
            $minTime[$u] = $time;
            foreach ($adj[$u] as [$v, $w]) {
                $nt = $time + $w;
                if ($nt <= $maxTime && $nt < $minTime[$v]) {
                    $nc = $cost + $passingFees[$v];
                    $pq->insert([$nc, $nt, $v], -$nc);
                }
            }
        }
        return -1;
    }
}
```

