    function minDays($grid) {
        $m = count($grid); $n = count($grid[0]);
        if ($this->count($grid, $m, $n) != 1) return 0;
        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $n; $j++) {
