                    $grid[$i][$j] = 0;
                    if ($this->count($grid, $m, $n) != 1) return 1;
                    $grid[$i][$j] = 1;
                }
            }
        }
        return 2;
    }

    private function count($grid, $m, $n) {
        $seen = array_fill(0, $m * $n, false);
