class Solution {

    /**
     * @param TreeNode $root
     * @return Integer
     */
    function minDepth($root) {
        if ($root === null) return 0;
        $queue = [$root];
        $depth = 1;
        while (!empty($queue)) {
            $next = [];
            $n = count($queue);
            for ($i = 0; $i < $n; $i++) {
                $node = $queue[$i];
