        $tc = [];
        for ($i = 0; $i < $m; $i++) $tc[$i] = ord($target[$i]) - 97;
        $tset = array_fill(0, 26, false);
        foreach ($tc as $c) $tset[$c] = true;
        $cnts = [];
        foreach ($stickers as $s) {
            $c = array_fill(0, 26, 0);
            $useful = false;
            $L = strlen($s);
