        foreach ($cnts as $idx => $c) {
            for ($x = 0; $x < 26; $x++) if ($c[$x] > 0) $byLetter[$x][] = $idx;
        }
        $full = (1 << $m) - 1;
        if ($full == 0) return 0;
        $dist = array_fill(0, $full + 1, -1);
        $dist[0] = 0;
        $queue = [0];
        $head = 0;
        while ($head < count($queue)) {
            $mask = $queue[$head++];
            $d = $dist[$mask];
            $first = 0;
