class StreamChecker {
    private $ch = [];
    private $fail = [];
    private $out = [];
    private $cur = 0;

    /**
     * @param String[] $words
     */
    function __construct($words) {
        $this->ch = [[]];
        $this->fail = [0];
        $this->out = [false];
        $cnt = 1;
        foreach ($words as $w) {
            $w = trim($w);
            $n = strlen($w);
            if ($n == 0) continue;
            $node = 0;
            for ($i = 0; $i < $n; $i++) {
                $c = $w[$i];
                if (!isset($this->ch[$node][$c])) {
                    $this->ch[$node][$c] = $cnt;
                    $this->ch[$cnt] = [];
                    $this->fail[$cnt] = 0;
                    $this->out[$cnt] = false;
                    $cnt++;
                }
                $node = $this->ch[$node][$c];
            }
            $this->out[$node] = true;
        }
        // BFS
        $queue = [];
        foreach ($this->ch[0] as $c => $v) {
            $this->fail[$v] = 0;
            $queue[] = $v;
        }
        $head = 0;
        while ($head < count($queue)) {
            $u = $queue[$head++];
            foreach ($this->ch[$u] as $c => $v) {
                $f = $this->fail[$u];
                while ($f != 0 && !isset($this->ch[$f][$c])) {
                    $f = $this->fail[$f];
                }
                if (isset($this->ch[$f][$c]) && $this->ch[$f][$c] != $v) {
                    $this->fail[$v] = $this->ch[$f][$c];
                } else {
                    $this->fail[$v] = 0;
                }
                if ($this->out[$this->fail[$v]]) $this->out[$v] = true;
                $queue[] = $v;
            }
        }
    }

    /**
     * @param String $letter
     * @return Boolean
     */
    function query($letter) {
        $c = trim($letter);
        if ($c === '') $c = $letter;
        $c = $c[0];
        $node = $this->cur;
        while ($node != 0 && !isset($this->ch[$node][$c])) {
            $node = $this->fail[$node];
        }
        if (isset($this->ch[$node][$c])) {
            $node = $this->ch[$node][$c];
        } else {
            $node = 0;
        }
        $this->cur = $node;
        return $this->out[$node];
    }
}

