class Solution {

    /**
     * @param String $beginWord
     * @param String $endWord
     * @param String[] $wordList
     * @return Integer
     */
    function ladderLength($beginWord, $endWord, $wordList) {
        $dict = array_flip($wordList);
        if (!isset($dict[$endWord])) return 0;
        $L = strlen($beginWord);
        $begin = [$beginWord => true];
        $end = [$endWord => true];
        unset($dict[$beginWord]);
        unset($dict[$endWord]);
        $steps = 1;
        $letters = range('a', 'z');
        while (!empty($begin) && !empty($end)) {
            if (count($begin) > count($end)) {
                $t = $begin; $begin = $end; $end = $t;
            }
            $steps++;
            $next = [];
            foreach ($begin as $w => $_) {
                for ($i = 0; $i < $L; $i++) {
                    $orig = $w[$i];
                    $cw = $w;
                    foreach ($letters as $c) {
                        if ($c === $orig) continue;
                        $cw[$i] = $c;
                        if (isset($end[$cw])) return $steps;
                        if (isset($dict[$cw])) {
                            $next[$cw] = true;
                            unset($dict[$cw]);
                        }
                    }
                }
            }
            $begin = $next;
        }
        return 0;
    }
}
